def edit(id, pairs,reason):
 p=Path('items')/(id+'.md'); old=p.read_text();new=old
 for a,b in pairs:
  assert new.count(a)==1,(id,a,new.count(a));new=new.replace(a,b)
 assert new!=old
 (base/'observed'/p.name).write_text(old);(base/'drafts'/p.name).write_text(new)
 changes.append(dict(id=id,path=str(p),before_raw_sha256=hashlib.sha256(old.encode()).hexdigest(),draft_raw_sha256=hashlib.sha256(new.encode()).hexdigest(),draft_path=str(base/'drafts'/p.name),reason=reason))
